fun HttpRequestBuilder.setJsonBody(body: String) {
    contentType(ContentType.Application.Json)
    setBody(body)
}

fun HttpRequestBuilder.setTurtleBody(body: String) {
    header(HttpHeaders.ContentType, "text/turtle")
    setBody(body)
}
